mapper.select:
SELECT 
FROM group_batch_task_item
WHERE task_id = #{taskId}
  AND status = #{pendingStatus}
ORDER BY id ASC
LIMIT #{limit}

mapper.update:
UPDATE group_batch_task_item
SET status = #{row.status},
    account_id = COALESCE(#{row.accountId}, account_id),
    group_jid = COALESCE(#{row.groupJid}, group_jid),
    error_code = #{row.errorCode},
    description = #{row.description},
    operated_at = #{row.operatedAt},
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}

  AND status = #{pendingStatus}

UPDATE group_batch_task_item
SET status = #{canceledStatus},
    operated_at = #{now},
    updated_at = #{now}
WHERE task_id = #{taskId}

  AND status = #{pendingStatus}
